-- The lexer: what a string literal can hold, how the escapes are read,
-- where a long comment starts and ends, and the numbers the scanner
-- accepts.  Everything is fed through 'load' as source text, so a
-- refusal is reported with the scanner's own message.
local function show(...)
  local n = select('#', ...)
  local t = {}
  for i = 1, n do
    local v = (select(i, ...))
    if type(v) == "string" then t[i] = string.format("%q", v)
    elseif v == nil then t[i] = "nil"
    else
      local ok, s = pcall(tostring, v)
      t[i] = ok and s or ("<" .. type(v) .. ">")
    end
  end
  return table.concat(t, "|")
end
-- Compile and run 'src', reporting refusal and raising alike.
local function comp(src)
  local f, e = load(src, "=c")
  if f == nil then return "refuse: " .. tostring(e) end
  local r = {pcall(f)}
  if not r[1] then return "raise: " .. tostring(r[2]) end
  local out = {}
  for i = 2, #r do out[i - 1] = show(r[i]) end
  return "ok: " .. table.concat(out, ",")
end
local function P(...) print(...) end

