print("== names and keywords ==")
for _, kw in ipairs({"and", "break", "do", "else", "elseif", "end", "false",
                     "for", "function", "goto", "if", "in", "local", "nil",
                     "not", "or", "repeat", "return", "then", "true", "until", "while"}) do
  P(kw, comp("local " .. kw .. " = 1 return 1"))
end
